<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;font-size:10px;color:#222}h1{font-size:18px}table{width:100%;border-collapse:collapse;margin-top:16px}th,td{border:1px solid #bbb;padding:5px;text-align:left}th{background:#eee}.right{text-align:right}</style></head><body><h1>Laporan Transaksi</h1><p>Dicetak: {{ now()->format('d M Y H:i') }}</p><p>Filter: {{ collect($filters)->filter()->map(fn ($value, $key) => $key.'='.$value)->join(', ') ?: 'Semua data' }}</p><table><thead><tr><th>No. Transaksi</th><th>Pelanggan</th><th>Produk</th><th>Status</th><th>Durasi</th><th>Dibayar</th><th class="right">Nominal</th></tr></thead><tbody>@foreach ($transactions as $transaction)<tr><td>{{ $transaction->number }}</td><td>{{ $transaction->user?->name ?: '-' }}<br>{{ $transaction->user?->email ?: '-' }}</td><td>{{ $transaction->product_name }}</td><td>{{ ucfirst($transaction->status) }}</td><td>{{ $transaction->duration_days }} hari<br>{{ $transaction->starts_at?->format('d M Y') }} - {{ $transaction->expires_at?->format('d M Y') }}</td><td>{{ $transaction->paid_at?->format('d M Y H:i') ?: '-' }}</td><td class="right">{{ config('app.currency', 'IDR') }} {{ number_format(($transaction->productOffering?->price ?? 0), 0, ',', '.') }}</td></tr>@endforeach</tbody><tfoot><tr><th colspan="6" class="right">Total</th><th class="right">{{ config('app.currency', 'IDR') }} {{ number_format($total, 0, ',', '.') }}</th></tr></tfoot></table></body></html>
